const items = $input.all();

const now = Date.now();
const sevenDaysAgo = now - 7 * 24 * 60 * 60 * 1000;
const seen = new Set();

const articles = items
  .map(item => item.json)
  .filter(itemData => {
    const title = itemData.title;
    const url = itemData.link || itemData.url;

    const date =
      itemData.isoDate ||
      itemData.pubDate ||
      itemData.published ||
      itemData.date;

    if (
      typeof title !== "string" ||
      typeof url !== "string" ||
      !date
    ) {
      return false;
    }

    const publishedAt = new Date(date).getTime();

    if (
      !Number.isFinite(publishedAt) ||
      publishedAt > now ||
      publishedAt < sevenDaysAgo
    ) {
      return false;
    }

    const key = url.trim().replace(/\/$/, "").toLowerCase();

    if (seen.has(key)) {
      return false;
    }

    seen.add(key);
    return true;
  })
  .sort((a, b) => {
    const dateA = new Date(
      a.isoDate || a.pubDate || a.published || a.date
    ).getTime();

    const dateB = new Date(
      b.isoDate || b.pubDate || b.published || b.date
    ).getTime();

    return dateB - dateA;
  })
  .slice(0, 10);

return articles.map(itemData => {
  return {
    json: {
      title: itemData.title,
      url: itemData.link || itemData.url,
      publishedAt:
        itemData.isoDate ||
        itemData.pubDate ||
        itemData.published ||
        itemData.date,
      content:
        itemData.contentSnippet ||
        itemData.description ||
        itemData.content ||
        ""
    }
  };
});
